// Objectif : rester sous la limite de tokens de la fenetre.
// Idee : garder les N derniers messages intacts, resumer le reste.

function reduireContexte(consignes, historique, N) {
  const recents = historique.slice(-N)        // les N messages recents, intacts
  const anciens = historique.slice(0, -N)     // tout le passe a condenser

  // On remplace le passe par un court resume (quelques tokens).
  const resume = resumer(anciens)             // ex: "Lea reserve Paris->Lisbonne, juin, 2 pers."

  // Les consignes importantes restent toujours en tete.
  return [
    consignes,
    { role: 'system', content: 'Resume de la discussion : ' + resume },
    ...recents
  ]
}

// Resultat : un contexte court mais qui conserve le role, les regles,
// les faits essentiels du passe et les derniers echanges.
